// Woo 订单 → 控制台 ingest 契约（upsert 幂等，只送 Woo 归属字段）
const orders = $input.all().map(i => i.json).filter(o => o && o.id);
const mapped = orders.map(o => ({
  woo_order_id: o.id,
  order_number: String(o.number || o.id),
  woo_status: String(o.status || 'pending'),
  customer_name: [((o.shipping||{}).first_name || (o.billing||{}).first_name || ''), ((o.shipping||{}).last_name || (o.billing||{}).last_name || '')].join(' ').trim() || null,
  country: (o.shipping||{}).country || (o.billing||{}).country || null,
  total: o.total || null,
  currency: o.currency || null,
  items_json: (o.line_items||[]).map(li => ({ name: li.name, qty: li.quantity, sku: li.sku || null })),
  placed_at: o.date_created_gmt ? (o.date_created_gmt + 'Z') : null,
}));
return [{ json: { orders: mapped } }];
